css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .ej-block:last-of-type{margin-bottom: 0;}
.mz .ej-block:last-of-type .serie-block:last-of-type{margin-bottom: 0;}
.mz .serie-cajas{display: flex; gap: 8px; flex-wrap: wrap; font-size: 18px; font-weight: 700; align-items: center;}
.mz .serie-cajas .caja-num{width: 62px; height: 48px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .serie-label{font-size: 13.5px; font-weight: 600; font-family: sans-serif; margin-bottom: 6px;}
.mz .serie-block{margin-bottom: 12px;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 150px; gap: 12px 0; align-items: center;}
.mz .unir-grid .u-serie{font-size: 18px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 9px 12px;}
.mz .unir-grid .u-salto{font-size: 17px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 10px 0; text-align: center;}
.mz .vf-fila{display: flex; align-items: center; gap: 12px; font-size: 15.5px; font-weight: 600; margin-bottom: 10px;}
.mz .vf-fila .frase{flex: 1; line-height: 1.3;}
.mz .vf-opts{display: flex; gap: 10px; flex-shrink: 0;}
.mz .vf-opts .vf{width: 34px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 16px;}
